        ahora = datetime.now(TZL)
        codigo = f"JUS-COEF-{re.sub(r'[^A-Za-z0-9]+', '-', unicodedata.normalize('NFD', cfg['id']).encode('ascii', 'ignore').decode()).upper()[:20]}-{anio}"
