"""Alta online de comunidades energeticas, gratuita (sin cuotas ni pagos).

La pagina de alta esta en la web (Astro, https://vatiaco.es/alta/) y llama a estas rutas
publicas (/cec-api/alta/*, con CORS para ALTA_ORIGENES):
  formulario (la comunidad se elige entre las del IDAE, las del mapa de la web; se registran
     los datos de su gestor) -> solicitud(): valida lo mismo que el panel del
     superusuario (plataforma.validar_comunidad) y guarda la solicitud (tabla alta de la base
     plataforma, con el hash de la contraseña del gestor)
  -> con ALTA_APROBACION (no se verifica el email) el gestor adjunta un documento que le
     acredita (acta, nombramiento...) y el alta queda en 'revision' hasta que el superusuario
     lo revisa y la aprueba (aprobar) o la rechaza (rechazar) en su panel
  -> crear() en segundo plano: plataforma.crear_comunidad, lo mismo que hace el superusuario
     (base de datos, tenant, paneles y usuario del gestor); el gestor entra con la contraseña
     que eligio en el formulario
  -> estado(): la pagina /alta/gracias/ pregunta hasta que la comunidad esta creada

El uso de la plataforma es gratuito y queda bajo la responsabilidad del gestor (condiciones
de uso de la web)."""
import base64
import binascii
import re
import secrets
import threading
import time

import psycopg
import requests
from psycopg.rows import dict_row
from psycopg.types.json import Jsonb

from . import db, plataforma
from .comun import E, log

URL = (E.get("ALTA_URL_PUBLICA") or "").rstrip("/")          # la plataforma (ThingsBoard)
WEB = (E.get("ALTA_URL_WEB") or "").rstrip("/")              # la web con la pagina de alta
MAX_DIA = int(E.get("ALTA_MAX_DIA") or 20)                   # altas online en 24 h (cada una crea tenant y base)
APROBACION = (E.get("ALTA_APROBACION") or "si") != "no"      # el superusuario aprueba cada alta
DOC_MAX_MB = 5                                               # documento acreditativo del gestor
DOC_TIPOS = ((b"%PDF-", "application/pdf", ".pdf"), (b"\x89PNG\r\n\x1a\n", "image/png", ".png"),
             (b"\xff\xd8\xff", "image/jpeg", ".jpg"))
_CREAR = threading.Lock()      # una comunidad a la vez
_IDAE = {"hasta": 0.0, "datos": {}}


class Errores(Exception):
    """Errores del formulario: {campo: mensaje} (campo "general" si no es de un campo)."""
    def __init__(self, errores):
        super().__init__("; ".join(errores.values()))
        self.errores = errores


def activa():
    return bool(WEB) and (E.get("ALTA_ONLINE") or "si") != "no"


def _cx():
    return psycopg.connect(db.dsn(plataforma.BASE), row_factory=dict_row, autocommit=True)


def preparar():
    """Las altas que se quedaron a medias (la API se reinicio mientras se creaban) pasan a error:
    el superusuario las reintenta desde su panel."""
    with _cx() as cx:
        cx.execute("UPDATE alta SET estado = 'error', error = 'Interrumpida al reiniciar la API', actualizado = now() "
                   "WHERE estado = 'creando'")


def info():
    """Lo que necesita la pagina de alta."""
    return {"activa": activa(), "nombre_servicio": E.get("ALTA_NOMBRE_SERVICIO") or "Plataforma de comunidades energéticas",
            "gratuita": True, "aprobacion": APROBACION, "documento": APROBACION, "documento_max_mb": DOC_MAX_MB,
            "url_condiciones": E.get("ALTA_URL_CONDICIONES") or "",
            "url_privacidad": E.get("ALTA_URL_PRIVACIDAD") or "", "url_plataforma": URL}


def _idae():
    """Comunidades energeticas del IDAE (las del mapa de la web): la web las publica en
    /data/comunidades-idae.json. Se leen una vez por hora."""
    if time.time() > _IDAE["hasta"]:
        r = requests.get(f"{WEB}/data/comunidades-idae.json", timeout=15)
        r.raise_for_status()
        cs = r.json()["comunidades"]
        n_mun = {}
        for c in cs:
            n_mun.setdefault(c["n"], set()).add(c["m"])
        _IDAE["datos"] = {(c["n"], c["m"]): dict(c, repetido=len(n_mun[c["n"]]) > 1) for c in cs}
        _IDAE["hasta"] = time.time() + 3600
    return _IDAE["datos"]


def _comunidad_idae(sel):
    """La comunidad elegida en el formulario ({n, m}: nombre y municipio en el IDAE) con sus
    datos del IDAE. El nombre en la plataforma lleva el municipio si el IDAE tiene varias con
    ese nombre."""
    sel = sel if isinstance(sel, dict) else {}
    try:
        c = _idae().get((str(sel.get("n") or ""), str(sel.get("m") or "")))
    except Exception:
        log.exception("comunidades del IDAE")
        raise Errores({"general": "No se puede consultar ahora la lista de comunidades del IDAE. Inténtalo en unos minutos."})
    if not c:
        raise Errores({"comunidad": "Elige tu comunidad de la lista (comunidades registradas en el IDAE)."})
    nombre = " ".join(c["n"].split())
    if c["repetido"]:
        nombre = f"{nombre[:118 - len(c['m'])]} ({c['m']})"
    return {"comunidad": nombre[:120].replace("|", "/"), "idae_nombre": c["n"], "municipio": c["m"], "provincia": c["p"],
            "autonomia": c.get("a"), "lat": c["lat"], "lon": c["lon"], "socios_idae": c.get("s"), "web": c.get("w")}


def _texto(v, minimo, maximo):
    t = " ".join(str(v or "").split())
    return t if minimo <= len(t) <= maximo and "|" not in t else None


def _documento(v):
    """Documento acreditativo del formulario ({nombre, datos: base64}) -> (bytes, nombre, tipo),
    o un mensaje de error. El tipo sale del contenido (PDF, PNG o JPG), no del nombre."""
    if not isinstance(v, dict) or not v.get("datos"):
        return "Adjunta un documento que acredite que eres gestor de la comunidad." if APROBACION else None
    try:
        b = base64.b64decode(str(v["datos"]), validate=True)
    except (binascii.Error, ValueError):
        return "No se ha podido leer el documento. Vuelve a adjuntarlo."
    if len(b) > DOC_MAX_MB * 1024 * 1024:
        return f"El documento ocupa más de {DOC_MAX_MB} MB."
    tipo = next((t for t in DOC_TIPOS if b.startswith(t[0])), None)
    if not tipo:
        return "El documento debe ser un PDF, JPG o PNG."
    nombre = re.sub(r"[^\w.\- ]", "_", str(v.get("nombre") or "documento"))[:80].strip(" .") or "documento"
    if not nombre.lower().endswith(tipo[2]):
        nombre += tipo[2]
    return b, nombre, tipo[1]


def _validar(f):
    """Formulario -> datos (o Errores por campo). La comunidad es una del IDAE (sus datos salen
    de alli); del formulario solo se registra el gestor. Lo de la comunidad y el gestor lo
    comprueba ademas plataforma.validar_comunidad, igual que en el panel del superusuario."""
    err = {}
    d = _comunidad_idae(f.get("idae"))
    d.update(contacto=_texto(f.get("contacto"), 3, 80), email=str(f.get("email") or "").strip().lower(),
             telefono=_texto(f.get("telefono"), 0, 30) or "")
    pw = str(f.get("password") or "")
    if not d["contacto"]:
        err["contacto"] = "Indica tu nombre y apellidos."
    if not plataforma.EMAIL.match(d["email"]) or len(d["email"]) > 120:
        err["email"] = "El email no es válido."
    if d["telefono"] and not re.match(r"^[+\d][\d\s]{6,19}$", d["telefono"]):
        err["telefono"] = "El teléfono no es válido."
    if len(pw) < 8:
        err["password"] = "La contraseña debe tener al menos 8 caracteres."
    elif pw != str(f.get("password2") or ""):
        err["password2"] = "Las contraseñas no coinciden."
    doc = _documento(f.get("documento"))
    if isinstance(doc, str):
        err["documento"] = doc
    if f.get("acepta") is not True:
        err["acepta"] = "Debes aceptar las condiciones de uso."
    if err:
        raise Errores(err)
    try:
        _, cid, *_ = plataforma.validar_comunidad({
            "nombre": d["comunidad"], "gestor_nombre": d["contacto"], "gestor_email": d["email"], "gestor_password": pw})
    except ValueError as e:
        if "gestor" in str(e) or "Email" in str(e):
            raise Errores({"email": str(e)})
        raise Errores({"comunidad": "Esta comunidad ya está dada de alta en la plataforma. Si eres su gestor, entra con tu usuario."})
    if plataforma._hashes_tb([d["email"]]):
        raise Errores({"email": "Ese email ya es usuario de la plataforma."})
    with _cx() as cx:   # otra alta con esa comunidad o ese gestor que aun no ha terminado
        if cx.execute("SELECT 1 FROM alta WHERE estado IN ('revision', 'pendiente', 'creando') AND (comunidad_id = %s OR datos->>'email' = %s)",
                      (cid, d["email"])).fetchone():
            raise Errores({"general": "Ya hay un alta en curso con esta comunidad o este email."})
    return d, cid, pw, doc or (None, None, None)


def solicitud(f):
    """Formulario de alta -> la comunidad se crea en segundo plano (tarda un minuto), o queda en
    revision si la aprueba el superusuario. La pagina va a /alta/gracias/?alta=<id>, que
    pregunta por su estado."""
    if not activa():
        raise Errores({"general": "El alta online no está disponible."})
    with _cx() as cx:
        n = cx.execute("SELECT count(*) AS n FROM alta WHERE creada > now() - interval '1 day'").fetchone()["n"]
    if n >= MAX_DIA:
        log.warning("alta online: tope de %s altas en 24 h alcanzado", MAX_DIA)
        raise Errores({"general": "Hoy se han recibido muchas altas. Inténtalo mañana o escríbenos a info@vatiaco.es."})
    d, cid, pw, doc = _validar(f)
    aid = secrets.token_urlsafe(12)
    with _cx() as cx:
        cx.execute("INSERT INTO alta (id, comunidad_id, datos, hash, socios, periodo, estado, documento, documento_nombre, "
                   "documento_tipo) VALUES (%s, %s, %s, %s, %s, 'gratuito', %s, %s, %s, %s)",
                   (aid, cid, Jsonb(d), plataforma._hash(pw), max(1, int(d["socios_idae"] or 0)),
                    "revision" if APROBACION else "pendiente", *doc))
    log.info("alta online: %s (%s) solicitada por %s", d["comunidad"], d["municipio"], d["email"])
    if not APROBACION:
        threading.Thread(target=crear, args=(aid,), name=f"alta-{aid}", daemon=True).start()
    return {"alta": aid}


def _fila(aid):
    with _cx() as cx:
        return cx.execute("SELECT * FROM alta WHERE id = %s", (aid,)).fetchone()


def crear(aid):
    """Crea la comunidad igual que el superusuario (plataforma.crear_comunidad) y pone al
    gestor la contraseña que eligio. Un reintento retoma la que se quedo a medias."""
    with _CREAR:
        with _cx() as cx:
            a = cx.execute("UPDATE alta SET estado = 'creando', error = NULL, actualizado = now() "
                           "WHERE id = %s AND estado IN ('pendiente', 'error') RETURNING *", (aid,)).fetchone()
        if not a:
            return _fila(aid)
        d, cid = a["datos"], a["comunidad_id"]
        try:
            tmp = secrets.token_urlsafe(18)    # se sustituye por el hash de la que eligio
            c = plataforma.por_id(cid)
            if c and (c["gestor_email"] or "").lower() == d["email"]:
                plataforma.aprovisionar(c, gestor_password=tmp)
            else:
                plataforma.crear_comunidad({
                    "id": cid, "nombre": d["comunidad"], "gestor_nombre": d["contacto"], "gestor_email": d["email"],
                    "gestor_telefono": d["telefono"], "gestor_password": tmp, "lat": d.get("lat"), "lon": d.get("lon")},
                    f"{E.get('SUPER_EMAIL') or 'superusuario'} (alta online)")
            if a["hash"]:
                plataforma._poner_hashes({d["email"]: a["hash"]})
                with _cx() as cx:
                    cx.execute("UPDATE gestor SET hash = %s WHERE comunidad = %s", (a["hash"], cid))
            with _cx() as cx:
                cx.execute("UPDATE alta SET estado = 'creada', comunidad = %s, hash = NULL, actualizado = now() "
                           "WHERE id = %s", (cid, aid))
            log.info("alta online: comunidad %s creada (%s, gestor %s)", cid, d["municipio"], d["email"])
        except Exception as e:
            log.exception("alta online %s (%s)", aid, cid)
            with _cx() as cx:
                cx.execute("UPDATE alta SET estado = 'error', error = %s, actualizado = now() WHERE id = %s",
                           (str(e)[-2000:], aid))
    return _fila(aid)


def estado(aid):
    """Para la pagina de confirmacion."""
    a = _fila(aid)
    if not a:
        raise KeyError(aid)
    return {"comunidad": a["datos"].get("comunidad"), "email": a["datos"].get("email"), "estado": a["estado"],
            "url_plataforma": URL}


# ---------------- superusuario ----------------
def lista():
    """Altas online y su estado."""
    with _cx() as cx:
        return [dict(r, creada=r["creada"].isoformat())
                for r in cx.execute(
                    "SELECT id, comunidad_id, comunidad, datos->>'comunidad' AS nombre, datos->>'municipio' AS municipio, datos->>'provincia' AS provincia, "
                    "datos->>'contacto' AS contacto, datos->>'email' AS email, socios, estado, error, creada, "
                    "documento_nombre FROM alta "
                    "ORDER BY creada DESC LIMIT 200").fetchall()]


def documento(aid):
    """Documento acreditativo de un alta -> (bytes, nombre, tipo)."""
    with _cx() as cx:
        a = cx.execute("SELECT documento, documento_nombre, documento_tipo FROM alta WHERE id = %s AND documento IS NOT NULL",
                       (aid,)).fetchone()
    if not a:
        raise KeyError(aid)
    return bytes(a["documento"]), a["documento_nombre"], a["documento_tipo"]


def reintentar(aid):
    a = _fila(aid)
    if not a:
        raise KeyError(aid)
    if a["estado"] != "error":
        raise ValueError("Solo se reintentan las altas con error")
    a = crear(aid)
    if a["estado"] == "error":
        raise RuntimeError(a["error"])
    return a["estado"]


def aprobar(aid):
    """El superusuario aprueba un alta en revision: se crea la comunidad (como en reintentar)."""
    with _cx() as cx:
        a = cx.execute("UPDATE alta SET estado = 'pendiente', actualizado = now() WHERE id = %s AND estado = 'revision' "
                       "RETURNING id", (aid,)).fetchone()
    if not a:
        if not _fila(aid):
            raise KeyError(aid)
        raise ValueError("Solo se aprueban las altas en revisión")
    a = crear(aid)
    if a["estado"] == "error":
        raise RuntimeError(a["error"])
    return a["estado"]


def rechazar(aid):
    """El superusuario rechaza un alta en revision: no se crea nada y se borran el hash de la
    contraseña y el documento. La comunidad y el email quedan libres para otra alta."""
    with _cx() as cx:
        a = cx.execute("UPDATE alta SET estado = 'rechazada', hash = NULL, documento = NULL, actualizado = now() "
                       "WHERE id = %s AND estado = 'revision' RETURNING id", (aid,)).fetchone()
    if not a:
        if not _fila(aid):
            raise KeyError(aid)
        raise ValueError("Solo se rechazan las altas en revisión")
    log.info("alta online %s rechazada", aid)
    return "rechazada"
__FASTAPI_EOF__

cat > config/fastapi/app/copias.py <<'__FASTAPI_EOF__'
"""Copias de seguridad de PostgreSQL en /backups (backups/postgres del stack, la misma carpeta
que la copia diaria del servicio pg-backup; se conserva al reinstalar con iot-thingsboard.sh).

Nombres: <base>-AAAA-MM-DD.dump (diaria, pg-backup) y <base>-<tipo>-AAAAMMDD-HHMMSS.dump
(tipo: manual, subida o previa = estado anterior a una restauracion). Formato pg_dump -Fc.
Las diarias y las que se hacen aqui tienen al lado la misma copia en SQL (<nombre>.sql.gz, con
INSERT y sin propietarios) para importarla en Adminer o con psql; el panel solo usa las .dump.

Cada funcion trabaja con las bases que se le permiten (bases=): el gestor, con la de su
comunidad (por defecto); el superusuario, con la de la plataforma y las de todas las
comunidades. La base de ThingsBoard tiene su copia diaria y se restaura a mano (README).

Paquete (copia completa): un .tar con varias .dump y manifiesto.json (fecha y de que es cada
una); se descarga de una vez y, al subirlo, cada .dump queda como copia "subida" de su base."""
import gzip
import hashlib
import io
import json
import os
import re
import secrets
import subprocess
import tarfile
import tempfile
import zipfile
from datetime import datetime, timedelta
from pathlib import Path

import psycopg
from psycopg import sql
from psycopg.rows import dict_row

from . import db
from .comun import TZL, comunidad, log

DIR = Path(os.environ.get("BACKUP_DIR", "/backups"))


def _propia():
    return [comunidad()["base"]]


def _re(base):
    b = re.escape(base)
    return re.compile(rf"^({b})-(\d{{4}}-\d{{2}}-\d{{2}})\.dump$"), \
        re.compile(rf"^({b})-(manual|subida|previa)-(\d{{8}}-\d{{6}})\.dump$")


# Bases que puede tener una copia (la de la plataforma o la de una comunidad; no la plantilla)
_BASE = re.compile(r"^(plataforma|cec_(?!plantilla$)[a-z0-9_]{2,30})$")


def _ajena(f):
    """Copia de una base valida que no esta entre las permitidas (p. ej. de una comunidad que aun
    no esta en la plataforma): se lista, descarga y borra, pero no se puede restaurar."""
    m = re.match(r"^([a-z0-9_]+)-", f.name)
    i = _info(f, [m.group(1)]) if m and _BASE.match(m.group(1)) else None
    return dict(i, restaurable=False) if i else None


def _pg(*args, timeout=3600):
    """Ejecuta pg_dump / pg_restore (PGHOST, PGUSER y PGPASSWORD vienen del entorno)."""
    env = dict(os.environ, PGOPTIONS="-c lock_timeout=30s")
    r = subprocess.run(args, env=env, capture_output=True, text=True, timeout=timeout)
    if r.returncode:
        raise RuntimeError((r.stderr or r.stdout or "error desconocido").strip()[-1500:])
    return r.stdout


def _sql(f):
    """Copia en SQL que acompaña a una .dump (base-tipo-fecha.dump -> base-tipo-fecha.sql.gz)."""
    return f.with_suffix(".sql.gz")


def _volcar_sql(base, f):
    """pg_dump en SQL plano (INSERT, sin propietarios ni permisos) comprimido en f. Se quitan las
    lineas \\restrict / \\unrestrict, que son ordenes de psql que Adminer no entiende."""
    tmp = f.with_name(f.name + ".tmp")
    env = dict(os.environ, PGOPTIONS="-c lock_timeout=30s")
    try:
        with tempfile.TemporaryFile() as err, gzip.open(tmp, "wb") as gz:
            p = subprocess.Popen(["pg_dump", "--inserts", "--no-owner", "--no-acl", "-d", base],
                                 env=env, stdout=subprocess.PIPE, stderr=err)
            for linea in p.stdout:
                if not re.match(rb"\\(un)?restrict ", linea):
                    gz.write(linea)
            if p.wait():
                err.seek(0)
                raise RuntimeError(err.read().decode(errors="replace").strip()[-1500:] or "error desconocido")
        tmp.rename(f)
    finally:
        tmp.unlink(missing_ok=True)


def _info(f, bases):
    for base in bases:
        diaria, otra = _re(base)
        m, o = diaria.match(f.name), otra.match(f.name)
        if m or o:
            st = f.stat()
            return {"nombre": f.name, "base": base, "restaurable": True, "tipo": "diaria" if m else o.group(2),
                    "bytes": st.st_size, "fecha": datetime.fromtimestamp(st.st_mtime, TZL).isoformat(timespec="seconds")}
    return None


def listar(bases=None, otras=False):
    """Copias de las bases permitidas (otras: tambien las de otras bases, marcadas no restaurables)."""
    bases = bases or _propia()
    if not DIR.is_dir():
        return []
    filas = (_info(f, bases) or (otras and _ajena(f)) for f in DIR.glob("*.dump"))
    return sorted(filter(None, filas), key=lambda x: x["fecha"], reverse=True)


def ruta(nombre, bases=None, otras=False):
    """Fichero de una copia de las bases permitidas (solo nombres de copia validos: nada de rutas)."""
    bases = bases or _propia()
    f = DIR / nombre
    if "/" in nombre or not f.is_file() or not (_info(f, bases) or (otras and _ajena(f))):
        raise KeyError(nombre)
    return f


def _nuevo(base, tipo):
    """Fichero nuevo para una copia; si ya hay uno de ese segundo (varias de la misma base en un
    paquete), el segundo siguiente."""
    t = datetime.now(TZL)
    while True:
        f = DIR / f"{base}-{tipo}-{t:%Y%m%d-%H%M%S}.dump"
        if not f.exists():
            return f
        t += timedelta(seconds=1)


def crear(bases=None, tipo="manual", permitidas=None):
    """Copia ahora (pg_dump -Fc) de las bases pedidas (por defecto, todas las permitidas)."""
    permitidas = permitidas or _propia()
    bases = bases or permitidas
    if set(bases) - set(permitidas):
        raise ValueError("Base de datos no permitida: " + ", ".join(sorted(set(bases) - set(permitidas))))
    out = []
    for base in bases:
        f = _nuevo(base, tipo)
        tmp = f.with_suffix(".tmp")
        try:
            _pg("pg_dump", "-Fc", "-d", base, "-f", str(tmp))
            tmp.rename(f)
        finally:
            tmp.unlink(missing_ok=True)
        try:
            _volcar_sql(base, _sql(f))
        except Exception:
            log.exception("copia SQL de %s", base)
        out.append(_info(f, [base]))
    return out


def subir(tmp, base=None, permitidas=None, otras=False):
    """Guarda como copia de `base` un fichero subido, si es un volcado pg_dump -Fc de ese tipo
    de base (de comunidad o de la plataforma). base "auto": la de la copia (su dbname). otras:
    admite tambien bases que no estan entre las permitidas (comunidades que aun no estan en la
    plataforma: se podran restaurar tras restaurar la plataforma que las registra)."""
    permitidas = permitidas or _propia()
    try:
        lista = _pg("pg_restore", "-l", str(tmp), timeout=300)
    except RuntimeError:
        raise ValueError("El fichero no es una copia de PostgreSQL (pg_dump -Fc)")
    m = re.search(r"^;\s+dbname: (\S+)", lista, re.M)
    origen = m.group(1) if m else None
    if base == "auto":
        if not origen:
            raise ValueError("La copia no dice de qué base es: elige la base")
        base = origen
    base = base or permitidas[0]
    if base not in permitidas and not (otras and _BASE.match(base)):
        raise ValueError(f"Base de datos no permitida: {base}")
    if base == "plataforma":
        if "TABLE public gestor " not in lista:
            raise ValueError("La copia no es de la base de la plataforma")
    elif "TABLE public socio " not in lista or "TABLE public consumo " not in lista:
        raise ValueError("La copia no es de una base de datos de comunidad")
    f = _nuevo(base, "subida")
    Path(tmp).rename(f)
    return dict(_info(f, [base]), origen=origen, restaurable=base in permitidas)


FORMATO_PAQUETE = "vatiaco-copias"


def paquete(nombres, bases=None, otras=False, titulos=None):
    """Junta en un .tar (temporal, en DIR; lo borra quien lo envia) las copias pedidas y un
    manifiesto.json con la fecha y de que base es cada una (titulos: base -> nombre legible)."""
    if not nombres:
        raise ValueError("No hay copias que juntar")
    fs = [ruta(n, bases, otras) for n in dict.fromkeys(nombres)]
    infos = [_info(f, bases or _propia()) or _ajena(f) for f in fs]
    man = {"formato": FORMATO_PAQUETE, "version": 1, "fecha": datetime.now(TZL).isoformat(timespec="seconds"),
           "copias": [{"fichero": i["nombre"], "base": i["base"], "tipo": i["tipo"], "fecha": i["fecha"],
                       "bytes": i["bytes"], "nombre": (titulos or {}).get(i["base"])} for i in infos]}
    tmp = DIR / f".paquete-{datetime.now(TZL):%Y%m%d-%H%M%S}-{os.getpid()}-{id(fs)}.tar"
    try:
        with tarfile.open(tmp, "w") as t:
            datos = json.dumps(man, ensure_ascii=False, indent=1).encode()
            ti = tarfile.TarInfo("manifiesto.json"); ti.size = len(datos); ti.mtime = int(datetime.now().timestamp())
            t.addfile(ti, io.BytesIO(datos))
            for f in fs:
                t.add(f, arcname=f.name)
    except BaseException:
        tmp.unlink(missing_ok=True)
        raise
    return tmp


def es_paquete(f):
    try:
        return tarfile.is_tarfile(f)
    except OSError:
        return False


def subir_paquete(tmp, permitidas=None, otras=False):
    """Guarda como copias "subidas" las .dump de un paquete (cada una, de la base que dice; no se
    sale de DIR: solo ficheros regulares con nombre de copia). Plataforma primero."""
    out, errores = [], []
    try:
        t = tarfile.open(tmp)
        miembros = t.getmembers()
    except tarfile.TarError as e:
        raise ValueError(f"El fichero .tar está dañado ({e})")
    with t:
        for m in miembros:
            n = Path(m.name).name
            if not m.isfile() or not n.endswith(".dump"):
                continue
            x = DIR / f".subida-{secrets.token_hex(8)}.tmp"
            try:
                with t.extractfile(m) as src, open(x, "wb") as dst:
                    while trozo := src.read(1 << 20):
                        dst.write(trozo)
                out.append(dict(subir(x, "auto", permitidas, otras), fichero=n))
            except ValueError as e:
                errores.append(f"{n}: {e}")
            finally:
                x.unlink(missing_ok=True)
    if not out:
        raise ValueError("El paquete no tiene copias válidas" + (": " + "; ".join(errores) if errores else ""))
    out.sort(key=lambda r: r["base"] != "plataforma")
    return out, errores


def registro(f):
    """Registro de la comunidad en la plataforma que guarda la copia (tabla plataforma_registro;
    lo tienen las copias de comunidad desde que existe la tabla), o None."""
    try:
        out = _pg("pg_restore", "-a", "-t", "plataforma_registro", "-f", "-", str(f), timeout=300)
    except RuntimeError:
        return None
    m = re.search(r"^COPY \S*plataforma_registro \(([^)]*)\) FROM stdin;\n(.+?)\n\\\.$", out, re.M | re.S)
    if not m:
        return None
    cols = [x.strip().strip('"') for x in m.group(1).split(",")]
    valores = m.group(2).split("\n")[0].split("\t")
    if "datos" not in cols or len(valores) != len(cols):
        return None
    # formato de texto de COPY: \\ \t \n \r escapados
    texto = re.sub(r"\\(.)", lambda x: {"t": "\t", "n": "\n", "r": "\r"}.get(x.group(1), x.group(1)),
                   valores[cols.index("datos")])
    try:
        return json.loads(texto)
    except ValueError:
        return None


def huella(f):
    """sha256 de un fichero de copia. El gestor solo puede volver a subir copias que se
    descargaron de la plataforma (su huella queda registrada: plataforma.huella_conocida): una
    hecha fuera podria llevar SQL arbitrario, y pg_restore lo ejecutaria con el usuario de
    PostgreSQL de la API."""
    h = hashlib.sha256()
    with open(f, "rb") as x:
        while trozo := x.read(1 << 20):
            h.update(trozo)
    return h.hexdigest()


_SECRETO = re.compile(r"hash|pass|token|secret", re.I)   # columnas que no salen en la exportacion
LEEME_EXPORTAR = """Datos de la comunidad exportados de la plataforma ({fecha}).

datadis/<CUPS>/   Los datos de cada suministro con los mismos ficheros y el mismo formato que
                  la descarga web de datadis.es: Consumo_ (curva de carga, con la energia
                  vertida, generada y autoconsumida), Potencias_ (maximetro), Contrato_ y
                  Energia_ (reactiva mensual). Punto y coma, coma decimal, campos entre
                  comillas, fechas AAAA/MM/DD y horas de fin de periodo. Se pueden volver a
                  cargar en la plataforma (pestaña Socios, Cargar CSV) o abrir con cualquier
                  herramienta que lea los ficheros de Datadis.
gestion/          El resto de tablas de la base de la comunidad (socios, reparto, gestion,
                  documentos...), una por fichero, con cabecera (UTF-8, separado por comas).

No incluye contraseñas ni claves de acceso, ni el contenido de los documentos PDF (se
descargan uno a uno desde Gestion). Para volver a cargar todo en la plataforma de una vez,
usa una copia .dump de la pestaña Base de datos.
"""
# Tablas de Datadis (las de su descarga web): salen en datadis/<CUPS>/ con su formato
DATADIS_EXPORTAR = ("consumo", "potencias", "energia", "contrato")
_CONTRATO_COLS = ["cups", "distribuidora", "comercializadora", "tarifaAcceso", "tensionConexion", "potenciaContratadakW",
                  "modoControlPotencia", "discriminacionHoraria", "fechaInicioVigencia", "fechaFinVigencia", "provincia",
                  "municipio", "codigoPostal", "potenciaTotalGenerada", "tipoAutoconsumo", "seccion", "subseccion",
                  "coeficienteReparto", "cau", "potenciaMaximaInstalacion"]
_CONTRATO_SIN_COMILLAS = {"distribuidora", "modoControlPotencia", "provincia", "municipio"}   # como en Datadis


def _dd(v, dec=3):
    """Numero con el formato de Datadis: entre comillas y con coma decimal (vacio si no hay)."""
    return "" if v is None else '"' + f"{v:.{dec}f}".replace(".", ",") + '"'


def _dn(v):
    """Numero del contrato como en Datadis: sin ceros de mas, coma decimal y entre comillas."""
    return "" if v is None else '"' + (f"{v:.3f}".rstrip("0").rstrip(".") or "0").replace(".", ",") + '"'


def _dt(v):
    """Texto entre comillas (vacio si no hay); fechas como AAAA/MM/DD."""
    if v is None or v == "":
        return ""
    if hasattr(v, "strftime"):
        v = v.strftime("%Y/%m/%d")
    return '"' + str(v).replace('"', "'") + '"'


def _exportar_datadis(cx, z):
    """Un directorio por CUPS con sus ficheros de la descarga web de Datadis. Devuelve los CUPS."""
    cx.row_factory = dict_row
    cupss = [r["cups"] for r in cx.execute(
        'SELECT DISTINCT "cups" FROM (SELECT "cups" FROM consumo UNION SELECT "cups" FROM potencias '
        'UNION SELECT "cups" FROM energia UNION SELECT "cups" FROM contrato) t ORDER BY 1').fetchall()]
    for cups in cupss:
        d0, d1 = cx.execute('SELECT min("fecha") AS a, max("fecha") AS b FROM consumo WHERE "cups" = %s', (cups,)).fetchone().values()
        suf = f"_{d0:%d-%m-%Y}_{d1:%d-%m-%Y}" if d0 else ""
        raiz = f"datadis/{cups}/"
        with z.open(f"{raiz}Consumo_{cups}{suf}.csv", "w") as f, cx.cursor(name="exp_consumo", row_factory=dict_row) as cur:
            f.write(b"cups;fecha;hora;consumo_kWh;metodoObtencion;energiaVertida_kWh;energiaGenerada_kWh;energiaAutoconsumida_kWh\n")
            cur.itersize = 5000
            cur.execute('SELECT * FROM consumo WHERE "cups" = %s ORDER BY ts', (cups,))
            for x in cur:
                f.write((";".join([_dt(x["cups"]), _dt(x["fecha"]), _dt(x["hora"]), _dd(x["consumo_kWh"]),
                                   x["metodoObtencion"] or "", _dd(x["energiaVertida_kWh"]), _dd(x["energiaGenerada_kWh"]),
                                   _dd(x["energiaAutoconsumida_kWh"])]) + "\n").encode())
        pot = cx.execute('SELECT * FROM potencias WHERE "cups" = %s '            # cada mes, por periodo
                         'ORDER BY date_trunc(\'month\', "fechaMaximo"), "periodo", "fechaMaximo"', (cups,)).fetchall()
        z.writestr(f"{raiz}Potencias_{cups}{suf}.csv", "cups;fechaMaximo;hora;maximoPotenciaDemandadaKW;periodo\n" + "".join(
            ";".join([_dt(x["cups"]), _dt(x["fechaMaximo"]), _dt(x["hora"]), _dd(x["maximoPotenciaDemandadaKW"]),
                      _dt(x["periodo"])]) + "\n" for x in pot))
        con = cx.execute('SELECT * FROM contrato WHERE "cups" = %s ORDER BY "fechaInicioVigencia"', (cups,)).fetchall()
        z.writestr(f"{raiz}Contrato_{cups}{suf}.csv", ";".join(_CONTRATO_COLS) + "\n" + "".join(
            ";".join(_dn(x[k]) if isinstance(x[k], float) else (x[k] or "") if k in _CONTRATO_SIN_COMILLAS else _dt(x[k])
                     for k in _CONTRATO_COLS) + "\n" for x in con))
        en = cx.execute('SELECT * FROM energia WHERE "cups" = %s ORDER BY "fecha"', (cups,)).fetchall()
        z.writestr(f"{raiz}Energia_{cups}{suf}.csv", "cups;fecha;" + ";".join(f"energiaP{p}" for p in range(1, 7)) + "\n" + "".join(
            ";".join([_dt(x["cups"]), _dt(x["fecha"].strftime("%Y/%m"))] + [_dd(x[f"energiaP{p}"]) for p in range(1, 7)]) + "\n"
            for x in en))
    return cupss


def exportar(base=None):
    """Todos los datos de la base en CSV en un .zip temporal en DIR (lo borra quien lo envia): los
    de Datadis de cada CUPS con los ficheros y el formato de su descarga web (datadis/<CUPS>/) y
    las demas tablas una por fichero, con cabecera (gestion/). Sin hashes, contraseñas ni tokens,
    ni columnas binarias."""
    base = base or _propia()[0]
    tmp = DIR / f".exportar-{secrets.token_hex(8)}.zip"
    try:
        with psycopg.connect(db.dsn(base)) as cx, zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as z:
            cols = {}
            for t, c in cx.execute("SELECT table_name, column_name FROM information_schema.columns "
                                   "WHERE table_schema = 'public' AND data_type <> 'bytea' "
                                   "AND table_name IN (SELECT table_name FROM information_schema.tables "
                                   "WHERE table_schema = 'public' AND table_type = 'BASE TABLE') "
                                   "ORDER BY table_name, ordinal_position").fetchall():
                if t != "plataforma_registro" and t not in DATADIS_EXPORTAR and not _SECRETO.search(c):
                    cols.setdefault(t, []).append(c)
            for t, cs in cols.items():
                q = sql.SQL("COPY (SELECT {} FROM {}) TO STDOUT WITH (FORMAT csv, HEADER)").format(
                    sql.SQL(", ").join(map(sql.Identifier, cs)), sql.Identifier(t))
                with z.open(f"gestion/{t}.csv", "w") as dst, cx.cursor().copy(q) as cp:
                    dst.write(b"\xef\xbb\xbf")   # BOM: las hojas de calculo lo abren en UTF-8
                    for trozo in cp:
                        dst.write(trozo)
            _exportar_datadis(cx, z)
            z.writestr("LEEME.txt", LEEME_EXPORTAR.format(fecha=datetime.now(TZL).strftime("%d/%m/%Y %H:%M")))
    except BaseException:
        tmp.unlink(missing_ok=True)
        raise
    return tmp


def borrar(nombre, bases=None, otras=False):
    f = ruta(nombre, bases, otras)
    f.unlink()
    _sql(f).unlink(missing_ok=True)


def restaurar(nombre, bases=None, previa=True):
    """Sustituye la base de la copia por su contenido, en una sola transaccion (si algo falla
    no cambia nada). Antes guarda el estado actual como copia "previa" (no si previa=False:
    base recien creada, vacia)."""
    f = ruta(nombre, bases)
    base = _info(f, bases or _propia())["base"]
    previa = crear([base], "previa", [base])[0] if previa else None
    _pg("pg_restore", "--clean", "--if-exists", "--no-owner", "--single-transaction", "-d", base, str(f))
    return {"restaurada": nombre, "base": base, "previa": previa}
