def _copias(f, *a):
    try:
        return f(*a)
    except KeyError:
        raise HTTPException(404, "No existe esa copia")
    except ValueError as e:
        raise HTTPException(422, str(e))
    except RuntimeError as e:
        raise HTTPException(500, f"PostgreSQL: {e}")


