  var T = sumaA(F.tot);
  q('.dd-k1').textContent = n ? eur(T) : '–';
  q('.dd-l1').textContent = 'Factura del año con IVA y generación (LCOE) (€)' + (com ? ' · en comunidad' : ' · en solitario') + (n && n < 12 ? ' · ' + n + ' meses' : '');
  q('.dd-k2').textContent = n ? eur(T / n) : '–';
