      if (sin.length) reg('Sin copias que restaurar: ' + sin.join(', ') + '.', fs.length ? '' : 'err');
      if (!fs.length) { cmsg('Esas bases no tienen copias (las previas no cuentan: restáuralas desde la lista).', 'err'); return; }
