    BACC[b.dataset.acc](bs);
  }; });
  q('c-completa').onclick = function () { hacer(P.bases.filter(function (b) { return b.registrada; }), true); };
  var ACC = {
    descargar: function (fs) {
      ctarea('Descargando ' + fs.length + (fs.length === 1 ? ' copia…' : ' copias…'), function () {
