  // Comunidades del gestor: pasar a otra (token de su usuario en ella) y crear una nueva
  function pintarCom(l) {
    q('ad-com-tabla').innerHTML = '<table><tr><th>Comunidad</th><th class="n">Socios</th><th>Estado</th><th></th></tr>' +
