          '</td><td>' + (x.actual ? '<span class="ad-chip ok">seleccionada</span>' : '<button class="ad-b sec" data-entrar="' + esc(x.id) + '">Seleccionar</button>') + '</td></tr>';
      }).join('') + '</table>';
    [].forEach.call(q('ad-com-tabla').querySelectorAll('[data-entrar]'), function (b) {
