.rp-b.sec { background: #f1e6f8; color: #7b2fa8; } .rp-b.peq { padding: 2px 8px; font-size: 12px; } .rp-b:disabled { opacity: .5; cursor: default; }
.rp-ctrl { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 6px; }
