.rp-pie input { width: 80px; font: inherit; padding: 3px 6px; border: 1px solid #ccc; border-radius: 4px; }
@media (max-width: 900px) { .rp-cuerpo { grid-template-columns: minmax(0, 1fr); } .rp-kpis { grid-template-columns: 1fr; } }
